    v25 = 0x536166654d6174683a207375627472616374696f6e206f766572666c6f770000fff6cae900000000000000000000000000000000000000000000000000000000;
    require(RETURNDATASIZE() >= 32);
    if (v18 <= v25.length) {
        if (v25.length - v18 >= amountOutMin) {
            if (deadline >= block.timestamp) {
                MEM[4 + MEM[64]] = _swapExactTokensForTokensSupportingFeeOnTransferTokens;
                require(bool(_setToken.code.size));
                v26 = _setToken.update(_swapExactTokensForTokensSupportingFeeOnTransferTokens, v3).gas(msg.gas);
                require(bool(v26), 0, RETURNDATASIZE()); // checks call status, propagates error data on error
                require(bool(_swapExactTokensForTokensSupportingFeeOnTransferTokens.code.size));
                v27 = _swapExactTokensForTokensSupportingFeeOnTransferTokens.sync().gas(msg.gas);
                require(bool(v27), 0, RETURNDATASIZE()); // checks call status, propagates error data on error
                stor_1_0_0 = 1;
                exit;
            } else {
                MEM[MEM[64] + 4] = 32;
                revert(Error('QiaoswapV2Router: EXPIRED'));
            }
        } else {
            MEM[4 + MEM[64]] = 32;
            revert(Error('QiaoswapV2Router: INSUFFICIENT_OUTPUT_AMOUNT', v28, v28, 0));
        }
    } else {
        MEM[MEM[64] + 4] = 32;
        v29 = new bytes[](v25.length);
        if (v25.length) {
            v30 = v25.data;
            v31 = v29.data;
            v29[0] = v25[0];
            v32 = v33 = 32;
            while (v32 < v25.length) {
                v29[v32] = v25[v32];
                v32 += 32;
            }
        }
        if (30) {
            MEM[v29.data] = ~0xffff & MEM[v29.data];
        }
        revert(Error(v29, v28, v28, 0));
    }
}

